/**
 * Every graticule variation, by the study that drew it, newest study first;
 * content.ts names and leads each study. A variation's id names its file in
 * public/marks/graticule/variations, which keeps the 256 unit square of
 * Graticule jaw, thicker and draws its ring at the same centre and outer
 * diameter, unless boxOf names the catalog mark whose drawn box it shares.
 */

/** One variation: its id, its name and what it draws or changes. */
export type VariationEntry = { readonly id: string; readonly name: string; readonly caption: string; readonly boxOf?: string };

